import{_ as e,a as r,c as t,ac as p}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Spark：Structured Streaming 的时间与输出边界","description":"区分有界批处理、watermark迟到保证、流去重和foreachBatch的提交边界。","frontmatter":{"title":"Spark：Structured Streaming 的时间与输出边界","description":"区分有界批处理、watermark迟到保证、流去重和foreachBatch的提交边界。","showdocs":{"topics":[{"id":"spark","title":"Spark","link":"/topics/spark/"}],"kind":"分区与流语义","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Spark：数据契约与分布执行","summary":"区分有界批处理、watermark迟到保证、流去重和foreachBatch的提交边界。","status":"active","related":[{"title":"Spark：订单批处理完整工程与推导","link":"/middleware/data-processing/spark/plus/practice/batch-project","kind":"批处理完整工程","scope":"general","audience":"general"},{"title":"Spark：DataFrame 与 SQL 的数据契约","link":"/middleware/data-processing/spark/plus/subjects/dataframe-sql","kind":"DataFrame与惰性执行","scope":"general","audience":"general"},{"title":"Spark 分区：shuffle、倾斜与计划排障","link":"/middleware/data-processing/spark/partition-diagnosis","kind":"分区与流语义","scope":"general","audience":"general"},{"title":"Spark：用途、惰性执行与 DAG","link":"/middleware/data-processing/spark/execution-model","kind":"DataFrame与惰性执行","scope":"general","audience":"general"}],"prev":{"text":"Spark：订单批处理完整工程与推导","link":"/middleware/data-processing/spark/plus/practice/batch-project"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Spark：订单批处理完整工程与推导","link":"/middleware/data-processing/spark/plus/practice/batch-project"},"next":false},"headers":[],"relativePath":"middleware/data-processing/spark/plus/subjects/streaming.md","filePath":"middleware/data-processing/spark/plus/subjects/streaming.md"}'),s={name:"middleware/data-processing/spark/plus/subjects/streaming.md"};function i(c,a,n,o,d,l){return r(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="spark-structured-streaming-的时间与输出边界" tabindex="-1">Spark：Structured Streaming 的时间与输出边界 <a class="header-anchor" href="#spark-structured-streaming-的时间与输出边界" aria-label="Permalink to &quot;Spark：Structured Streaming 的时间与输出边界&quot;">​</a></h1><p>前置：DataFrame转换/action和聚合。可对照<a href="/middleware/data-processing/spark/plus/practice/batch-project#project">已交付的有界订单批处理</a>理解输入快照；本页只讲持续输入的设计边界，没有可运行流程序。本文固定Apache Spark/PySpark 3.5.6版本族，运行前应核对所在集群版本；不是对4.x的兼容承诺。本轮只写作与静态解析，示例未执行，不启动Spark、JVM或外部服务。</p><h2 id="batch-stream" tabindex="-1">Spark 批处理与流处理 <a class="header-anchor" href="#batch-stream" aria-label="Permalink to &quot;Spark 批处理与流处理 {#batch-stream}&quot;">​</a></h2><p>Spark 批处理与流处理的区别首先是输入有界与持续增量。Structured Streaming用相近DataFrame/SQL表达式持续维护结果，通常按微批执行；这不等于把批处理脚本放进while循环。readStream不能直接collect或普通write来结束查询，必须定义writeStream、checkpoint与生命周期。</p><p>本包只提供完整批处理工程，不提供半成品流程序；以下是设计边界，未启动任何流查询。传统Spark Streaming的DStream与Structured Streaming不是同一个API。若需求是每天固定快照离线结算，批处理更便于复算；若需持续事件时间窗口，要进一步定义迟到容忍、状态保留和下游幂等。</p><h2 id="watermark" tabindex="-1">Spark watermark 迟到边界 <a class="header-anchor" href="#watermark" aria-label="Permalink to &quot;Spark watermark 迟到边界 {#watermark}&quot;">​</a></h2><p>Spark watermark 迟到边界以观察到的事件时间进展减延迟阈值为基础，用来约束状态保留和窗口完成；它不是墙上时钟，也不保证空闲输入时持续前进。必须在适当的事件时间列上、聚合或去重之前设置，才能满足相应操作的状态清理条件。多流查询的全局watermark还受慢流与策略影响。</p><p>阈值内的迟到数据满足官方保证时不会因过晚被丢弃，超过阈值的数据可能被处理也可能丢弃，不能承诺“严格大于10分钟的一律拒绝”。窗口append模式通常等watermark越过窗口结束才能输出最终行；complete模式保留完整结果表，不能期待相同的状态清理行为。迟到阈值是业务准确性与资源上限之间的契约。</p><h2 id="dedup-output" tabindex="-1">Spark 流去重与输出模式 <a class="header-anchor" href="#dedup-output" aria-label="Permalink to &quot;Spark 流去重与输出模式 {#dedup-output}&quot;">​</a></h2><p>Spark 流去重与输出模式必须一起设计。3.5新增dropDuplicatesWithinWatermark需要先设置watermark，可在指定延迟范围内按事件ID去重；超出保留范围的重复不能保证仍被识别。批处理dropDuplicates只处理当前快照，不能直接宣称跨批永久唯一。永久去重需要持久业务键索引及成本模型。</p><p>append、update、complete是否可用取决于查询和sink；update会重发变化的结果行，下游只追加将产生重复。foreachBatch默认至少一次，重试可再次调用同一batchId；要用批次ID或业务键实现幂等并处理多sink提交。checkpoint记录offset与状态，但不能让不支持事务的外部写入自动exactly-once。修改状态schema、分组键或去重算子后不得盲用旧checkpoint；应按官方兼容范围迁移并安排重放与去重。</p><h2 id="sources" tabindex="-1">资料与版本核对 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;资料与版本核对 {#sources}&quot;">​</a></h2><p>英文以官方3.5.6固定版本文档为准；中文作者资料用于术语与入门路径，不据旧版教程推断3.5新增API。核对日期：2026-10-17。</p><ul><li><a href="https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html" target="_blank" rel="noopener noreferrer">Structured Streaming 3.5.6</a></li><li><a href="https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.dropDuplicatesWithinWatermark.html" target="_blank" rel="noopener noreferrer">3.5 watermark去重API</a></li></ul><p><a href="/topics/spark/">返回 Spark 专题</a> · <a href="/topics/spark/?route=p2-spark">继续学习路线</a></p>',15)])])}const m=e(s,[["render",i]]);export{u as __pageData,m as default};
